/**
 * Independent local FFmpeg queue. Nothing is generated by paid AI APIs.
 * Requires dedicated HQ DB and HQ media volume, no SPLCART network/credentials.
 */
import { randomUUID } from "node:crypto";
import { db } from "../lib/prisma";
import { renderProductReel } from "../lib/creative";
import { scheduleToday } from "../lib/creative-schedule";

if(!process.env.DATABASE_URL || !process.env.HQ_MEDIA_DIR)
  throw new Error("CREATIVE_HQ_DATABASE_AND_MEDIA_VOLUME_REQUIRED");
if(process.env.HQ_MEDIA_DIR.includes("splcart"))
  throw new Error("CREATIVE_STORE_MEDIA_VOLUME_FORBIDDEN");

async function renderNext():Promise<boolean>{
  // A crashed process must not leave 'rendering' status forever or claim a completed video.
  await db.reelJob.updateMany({
    where:{status:"RENDERING",startedAt:{lt:new Date(Date.now()-12*60_000)}},
    data:{status:"FAILED",errorCode:"WORKER_INTERRUPTED",finishedAt:new Date()},
  });
  const oldest=await db.reelJob.findFirst({
    where:{status:"QUEUED"},orderBy:{createdAt:"asc"},include:{asset:true},
  });
  if(!oldest)return false;
  const acquired=await db.reelJob.updateMany({
    where:{id:oldest.id,status:"QUEUED"},
    data:{status:"RENDERING",startedAt:new Date(),errorCode:null},
  });
  if(acquired.count!==1)return true;
  const filename=randomUUID()+".mp4";
  try{
    const output=await renderProductReel({
      imageFilename:oldest.asset.filename,
      outputFilename:filename,
      title:oldest.titleSnapshot,
      material:oldest.materialSnapshot,
      ownerLink:oldest.linkSnapshot,
      durationSeconds:oldest.durationSeconds,
    });
    await db.$transaction(async tx=>{
      await tx.reelJob.update({where:{id:oldest.id},
        data:{status:"RENDERED",outputFilename:output.filename,finishedAt:new Date()}});
      await tx.systemAudit.create({data:{event:"REEL_RENDERED_LOCALLY",
        actor:"HQ_CODE_RENDER_WORKER",reason:"Real silent "+output.durationSeconds+
          "-second MP4 completed from an owner photo. Reel "+oldest.id+"; "+output.bytes+
          " bytes. No social publishing."}});
    });
    console.log("REEL_RENDERED",oldest.id,output.bytes);
  }catch(error){
    const code=error instanceof Error && error.message.startsWith("INVALID_")
      ?error.message.slice(0,70):"FFMPEG_RENDER_FAILED";
    await db.reelJob.update({where:{id:oldest.id},
      data:{status:"FAILED",errorCode:code,finishedAt:new Date()}});
    console.error("REEL_FAILED",oldest.id,code);
  }
  return true;
}
async function runWorker(){
 try{
  if(process.argv.includes("--schedule-only")){
    const result=await scheduleToday();
    console.log("CREATIVE_SCHEDULE",JSON.stringify(result));
    return;
  }
  const once=process.argv.includes("--once");
  if(once){
    const didWork=await renderNext();
    if(!didWork)console.log("CREATIVE_QUEUE_EMPTY");
  }else{
    // Only local owner-approved photos are ever scheduled; videos await approval.
    // Five-minute poll checks the India-local date without API keys or cron vendor.
    let lastScheduleCheck=0;
    for(;;){
      if(Date.now()-lastScheduleCheck>300_000){
        lastScheduleCheck=Date.now();
        try{
          const result=await scheduleToday();
          if(result.created>0)console.log("CREATIVE_SCHEDULE",JSON.stringify(result));
        }catch(e){console.error("CREATIVE_SCHEDULE_FAILED",e instanceof Error?e.message:"unknown");}
      }
      const didWork=await renderNext();
      if(!didWork)await new Promise(resolve=>setTimeout(resolve,3000));
    }
  }
}finally {await db.$disconnect();}
}
void runWorker().catch(error=>{console.error("CREATIVE_WORKER_FATAL",error instanceof Error?error.message:"unknown");process.exitCode=1;});
